import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"淘汰策略","description":"","frontmatter":{},"headers":[],"relativePath":"database/redis/basic/remove.md","filePath":"database/redis/basic/remove.md"}`),a={name:`database/redis/basic/remove.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="淘汰策略" tabindex="-1">淘汰策略 <a class="header-anchor" href="#淘汰策略" aria-label="Permalink to “淘汰策略”">​</a></h1><ul><li>内存超过redis最大内存限制，会根据配置的淘汰策略，淘汰键值对。</li></ul><h2 id="配置策略" tabindex="-1">配置策略 <a class="header-anchor" href="#配置策略" aria-label="Permalink to “配置策略”">​</a></h2><div class="language-ini" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory 100mb </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 设置最大内存限制（必须先配置）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory-policy allkeys-lru </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 设置淘汰策略</span></span></code></pre></div><h2 id="策略模式" tabindex="-1">策略模式 <a class="header-anchor" href="#策略模式" aria-label="Permalink to “策略模式”">​</a></h2><h3 id="不淘汰" tabindex="-1">不淘汰 <a class="header-anchor" href="#不淘汰" aria-label="Permalink to “不淘汰”">​</a></h3><ul><li><code>noeviction</code>：默认配置，不淘汰任何键，内存满时拒绝新写入操作（返回错误）</li></ul><h3 id="只淘汰设置了过期时间的键" tabindex="-1">只淘汰设置了过期时间的键 <a class="header-anchor" href="#只淘汰设置了过期时间的键" aria-label="Permalink to “只淘汰设置了过期时间的键”">​</a></h3><ul><li><code>volatile-lru</code>：淘汰最近最少使用（LRU） 的过期键</li><li><code>volatile-lfu</code>：淘汰最近最少频率使用（LFU）</li><li><code>volatile-ttl</code>：淘汰剩余过期时间最短的键</li><li><code>volatile-random</code>：随机淘汰过期键</li></ul><h3 id="淘汰所有键-不管是否设置过期时间" tabindex="-1">淘汰所有键（不管是否设置过期时间） <a class="header-anchor" href="#淘汰所有键-不管是否设置过期时间" aria-label="Permalink to “淘汰所有键（不管是否设置过期时间）”">​</a></h3><ul><li><code>allkeys-lru</code>：淘汰所有键中最近最少使用的键</li><li><code>allkeys-lfu</code>：淘汰所有键中最近最少频率使用的键（4.0+）</li><li><code>allkeys-random</code>：随机淘汰所有键中的键</li></ul><h2 id="选择建议" tabindex="-1">选择建议 <a class="header-anchor" href="#选择建议" aria-label="Permalink to “选择建议”">​</a></h2><ul><li>缓存场景（如会话缓存）：推荐 <code>allkeys-lru</code> 或 <code>allkeys-lfu</code>，优先保留热点数据</li><li>有明确过期时间的场景：使用 <code>volatile-lru</code> 或 <code>volatile-ttl</code></li><li>均匀访问场景：<code>allkeys-random</code> 更适合</li><li>不允许数据丢失：使用 <code>noeviction</code>（需确保内存充足）</li></ul>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};